<?php if ($page==='register'): ?><label>Confirm password<input type="password" name="password_confirmation" autocomplete="new-password" minlength="12" maxlength="72" required></label><p class="field-help">Supplier accounts require administrator verification before publishing products.</p><?php endif ?>
